"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One link in the list. */
export interface RollLink {
  label: string;
  href: string;
}

/** Props for a list of rolling links. */
export type RollLinksProps = Omit<ComponentPropsWithoutRef<"nav">, "children"> & {
  links: RollLink[];
  /** Names the navigation for screen readers, for example "Primary". */
  label: string;
  /** The `href` of the page the person is on. That link gets `aria-current="page"` and a marker. */
  currentHref?: string;
};

const ROLL_SECONDS = 0.35;
// Each letter starts this long after the one before it.
const STAGGER_SECONDS = 0.025;
// A long label still finishes on time: past this many letters the stagger shrinks to fit.
const MAX_STAGGER_SECONDS = 0.25;
const EASE_OUT = [0.165, 0.84, 0.44, 1] as const;
const INSTANT: Transition = { duration: 0 };

/**
 * A short list of large text links for site navigation. Pointing at a link,
 * or moving focus to it, rolls its letters up one after another to an
 * identical copy and dims the other links.
 */
export function RollLinks({ links, label, currentHref, className, ...navProps }: RollLinksProps) {
  // Hover and focus are tracked apart, so a pointer that leaves does not undim a link the keyboard is on.
  const [hovered, setHovered] = useState<string | null>(null);
  const [focused, setFocused] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();
  const active = hovered ?? focused;

  return (
    <nav {...navProps} aria-label={label} className={cn("w-full max-w-sm", className)}>
      <ul className="flex flex-col">
        {links.map((link) => {
          const letters = Array.from(link.label);
          const rolled = active === link.href && !reduceMotion;
          const gap = Math.min(STAGGER_SECONDS, MAX_STAGGER_SECONDS / Math.max(letters.length, 1));
          const isCurrent = link.href === currentHref;
          return (
            <li key={link.href}>
              <a
                href={link.href}
                aria-current={isCurrent ? "page" : undefined}
                // A touch has no hover, and a hover left behind by a tap would keep the list dimmed.
                onPointerEnter={(event) => {
                  if (event.pointerType === "mouse") setHovered(link.href);
                }}
                onPointerLeave={() => setHovered(null)}
                onFocus={() => setFocused(link.href)}
                onBlur={() => setFocused(null)}
                className={cn(
                  "inline-flex min-h-11 items-center gap-3 rounded-lg text-3xl font-semibold tracking-tight text-foreground outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-4 focus-visible:ring-offset-background motion-safe:transition-opacity motion-safe:duration-200",
                  active !== null && active !== link.href ? "opacity-50" : "opacity-100",
                )}
              >
                {/* The letters below are split for the roll, so the whole label is read from here, once. */}
                <span className="sr-only">{link.label}</span>
                <span aria-hidden="true" className="flex whitespace-pre">
                  {letters.map((letter, index) => (
                    // Letters repeat and never reorder, so the place in the word is the identity.
                    <span key={`${index}-${letter}`} className="relative inline-block overflow-hidden leading-tight">
                      <motion.span
                        initial={false}
                        animate={{ y: rolled ? "-100%" : "0%" }}
                        transition={reduceMotion ? INSTANT : { duration: ROLL_SECONDS, ease: EASE_OUT, delay: index * gap }}
                        className="relative block"
                      >
                        {letter}
                        <span className="absolute top-full left-0">{letter}</span>
                      </motion.span>
                    </span>
                  ))}
                </span>
                {isCurrent ? <span aria-hidden="true" className="size-2 shrink-0 rounded-full bg-primary" /> : null}
              </a>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}
